from aiogram import Router, F
from aiogram.types import Message, ChatJoinRequest, Chat
from ..models import User
from ..billing import PaymentProcessorFactory
from ..document_processing import process_user_document

router = Router()

@router.message(F.new_chat_members)
async def on_group_join(message: Message):
    if message.new_chat_members and any(bot.id == m.id for m in message.new_chat_members):
        user = User.get_by_telegram_id(message.from_user.id)
        if not user.subscription_active:
            processor = PaymentProcessorFactory.get_processor()
            processor.charge_subscription(str(user.id))

@router.message()
async def handle_message(message: Message):
    user = User.get_or_create(message.from_user.id)
    
    if not user.has_seen_disclaimer:
        await message.answer("⚠️ This is a legal research assistant, not a lawyer. Always consult with a qualified attorney for legal advice.")
        user.has_seen_disclaimer = True
        user.save()
    
    if message.document:
        processor = PaymentProcessorFactory.get_processor()
        page_count = estimate_page_count(message.document)
        charge_result = processor.charge_document_analysis(str(user.id), page_count)
        
        if charge_result["success"]:
            analysis = process_user_document(message.document, user.id, is_user_uploaded=True)
            await message.answer(f"Document analysis: {analysis.summary}")
        else:
            await message.answer("Payment required to process document")

