from ..corpus import LegalCorpus

def process_user_document(document, user_id, is_user_uploaded: bool = False):
    analysis = LegalCorpus.analyze(document)
    analysis.user_uploaded = True
    analysis.unverified = True
    analysis.user_id = user_id
    return analysis

