# juris_kai/tests/test_security.py
import importlib.util
import os
from pathlib import Path

def test_import_boundaries():
    forbidden_modules = {
        'core.build_manager',
        'core.approval',
        'core.deployment_manager'
    }
    
    package_root = Path(__file__).parent.parent
    for py_file in package_root.rglob('*.py'):
        if 'juris_kai' in str(py_file) and '__init__' not in str(py_file):
            spec = importlib.util.spec_from_file_location("module", str(py_file))
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            
            for name in dir(module):
                obj = getattr(module, name)
                if hasattr(obj, '__module__') and obj.__module__ in forbidden_modules:
                    raise ImportError(f"Security violation: {py_file} imports forbidden module {obj.__module__}")

